import React, { useState, useEffect } from 'react';
import { Dialog, DialogContent, DialogHeader, DialogTitle, DialogFooter, DialogDescription } from '../ui/dialog';
import { Button } from '../ui/button';
import { Textarea } from '../ui/textarea';
import CriteriaRating from './CriteriaRating';
import { Star } from 'lucide-react';
import { toast } from 'sonner';

const defaultCriteria = {
    cleanliness: 0,
    accuracy: 0,
    communication: 0,
    location: 0,
    value: 0
};

const ReviewForm = ({ isOpen, onClose, onSubmit, initialData = null, isSubmitting = false }) => {
    const [rating, setRating] = useState(0);
    const [criteria, setCriteria] = useState(defaultCriteria);
    const [text, setText] = useState('');

    useEffect(() => {
        if (isOpen) {
            if (initialData) {
                setRating(initialData.rating || 0);
                setCriteria(initialData.criteria || defaultCriteria);
                setText(initialData.text || '');
            } else {
                setRating(0);
                setCriteria(defaultCriteria);
                setText('');
            }
        }
    }, [isOpen, initialData]);

    const handleCriteriaChange = (key, value) => {
        setCriteria(prev => ({ ...prev, [key]: value }));
    };

    const handleSubmit = () => {
        // Validation
        if (rating === 0) {
            toast.error("Please provide an overall rating");
            return;
        }
        
        for (const [key, value] of Object.entries(criteria)) {
            if (value === 0) {
                toast.error(`Please provide a rating for ${key}`);
                return;
            }
        }

        if (text.length > 0 && text.length < 20) {
            toast.error("Review text must be at least 20 characters");
            return;
        }

        if (text.length > 1000) {
            toast.error("Review text cannot exceed 1000 characters");
            return;
        }

        onSubmit({ rating, criteria, text });
    };

    const isEditMode = !!initialData;

    return (
        <Dialog open={isOpen} onOpenChange={onClose}>
            <DialogContent className="sm:max-w-[500px] max-h-[90vh] overflow-y-auto">
                <DialogHeader>
                    <DialogTitle>{isEditMode ? 'Edit Your Review' : 'Write a Review'}</DialogTitle>
                    <DialogDescription>
                        Share your experience to help other students make better choices.
                    </DialogDescription>
                </DialogHeader>

                <div className="py-4 space-y-6">
                    {/* Overall Rating */}
                    <div className="flex flex-col items-center space-y-2 pb-4 border-b">
                        <span className="text-sm font-medium text-slate-700">Overall Rating</span>
                        <div className="flex items-center space-x-1">
                            {[1, 2, 3, 4, 5].map((star) => (
                                <button
                                    key={star}
                                    type="button"
                                    onClick={() => setRating(star)}
                                    className="focus:outline-none transition-transform hover:scale-110 cursor-pointer"
                                >
                                    <Star
                                        className={`w-8 h-8 ${
                                            star <= rating
                                                ? 'fill-amber-400 text-amber-400'
                                                : 'fill-transparent text-slate-300'
                                        }`}
                                    />
                                </button>
                            ))}
                        </div>
                    </div>

                    {/* Criteria Ratings */}
                    <div className="space-y-1">
                        <CriteriaRating label="Cleanliness" value={criteria.cleanliness} onChange={(v) => handleCriteriaChange('cleanliness', v)} />
                        <CriteriaRating label="Accuracy" value={criteria.accuracy} onChange={(v) => handleCriteriaChange('accuracy', v)} />
                        <CriteriaRating label="Communication" value={criteria.communication} onChange={(v) => handleCriteriaChange('communication', v)} />
                        <CriteriaRating label="Location" value={criteria.location} onChange={(v) => handleCriteriaChange('location', v)} />
                        <CriteriaRating label="Value" value={criteria.value} onChange={(v) => handleCriteriaChange('value', v)} />
                    </div>

                    {/* Review Text */}
                    <div className="space-y-2">
                        <div className="flex justify-between items-end">
                            <label htmlFor="review-text" className="text-sm font-medium text-slate-700">
                                Written Review (Optional)
                            </label>
                            <span className={`text-xs ${text.length > 1000 ? 'text-red-500' : 'text-slate-500'}`}>
                                {text.length}/1000
                            </span>
                        </div>
                        <Textarea
                            id="review-text"
                            placeholder="Tell us about your stay. What did you love? What could be improved?"
                            value={text}
                            onChange={(e) => setText(e.target.value)}
                            className="min-h-[120px] resize-y"
                        />
                        {text.length > 0 && text.length < 20 && (
                            <p className="text-xs text-red-500">Please write at least 20 characters.</p>
                        )}
                    </div>
                </div>

                <DialogFooter className="sm:justify-end gap-2 mt-2">
                    <Button type="button" variant="outline" onClick={onClose} disabled={isSubmitting}>
                        Cancel
                    </Button>
                    <Button type="button" onClick={handleSubmit} disabled={isSubmitting}>
                        {isSubmitting ? 'Submitting...' : isEditMode ? 'Update Review' : 'Submit Review'}
                    </Button>
                </DialogFooter>
            </DialogContent>
        </Dialog>
    );
};

export default ReviewForm;