import React, { useState } from 'react';
import { Button } from "../../components/ui/button";
import { Input } from "../../components/ui/input";
import { Label } from "../../components/ui/label";
import { Dialog, DialogContent, DialogHeader, DialogTitle, DialogDescription, DialogFooter } from "../../components/ui/dialog";
import { CreditCard, Lock, Check, Loader2 } from 'lucide-react';
import { confirmPayment } from '../../api/listingService';
import { toast } from "sonner";
import { DatePicker } from '../ui/date-picker';

const PaymentModal = ({ isOpen, onClose, booking, onSuccess }) => {
    const [loading, setLoading] = useState(false);
    const [name, setName] = useState('');
    const [moveInDate, setMoveInDate] = useState(null);
    const [confirmedDemo, setConfirmedDemo] = useState(false);

    const handlePayment = async (e) => {
        e.preventDefault();

        if (!confirmedDemo) {
            toast.error("Please confirm this is a demo payment");
            return;
        }

        setLoading(true);

        try {
            await confirmPayment(booking.booking_id, 'card');
            toast.success("Payment successful! Your booking is confirmed.");
            onSuccess();
            handleClose();
        } catch (error) {
            toast.error(error.message || "Payment failed. Please try again.");
        } finally {
            setLoading(false);
        }
    };

    const handleClose = () => {
        setName('');
        setMoveInDate(null);
        setConfirmedDemo(false);
        onClose();
    };

    return (
        <Dialog open={isOpen} onOpenChange={handleClose}>
            <DialogContent className="sm:max-w-md">
                <DialogHeader>
                    <DialogTitle className="flex items-center gap-2">
                        <CreditCard className="h-5 w-5" />
                        Complete Payment
                    </DialogTitle>
                    <DialogDescription>
                        Booking for {booking?.itemName} - ₹{booking?.rent || '0'}/month
                    </DialogDescription>
                </DialogHeader>

                <form onSubmit={handlePayment} className="space-y-4">
                    <div className="space-y-2">
                        <Label>Move-in Date</Label>
                        <DatePicker
                            date={moveInDate}
                            onDateChange={setMoveInDate}
                            className="w-full"
                            disabled={(date) => date < new Date(new Date().setHours(0, 0, 0, 0))}
                        />
                    </div>

                    <div className="space-y-2">
                        <Label htmlFor="name">Cardholder Name</Label>
                        <Input
                            id="name"
                            placeholder="John Doe"
                            value={name}
                            onChange={(e) => setName(e.target.value)}
                        />
                    </div>

                    <div className="bg-amber-50 border border-amber-200 rounded-lg p-4">
                        <div className="flex items-start gap-3">
                            <Lock className="h-5 w-5 text-amber-600 mt-0.5" />
                            <div>
                                <p className="font-medium text-amber-800 text-sm">Demo Payment</p>
                                <p className="text-xs text-amber-600 mt-1">Demo Mode - No real payment will be processed. This is a simulated transaction for testing purposes.</p>
                            </div>
                        </div>
                    </div>

                    <div className="flex items-start gap-2">
                        <input
                            type="checkbox"
                            id="confirmDemo"
                            checked={confirmedDemo}
                            onChange={(e) => setConfirmedDemo(e.target.checked)}
                            className="mt-1 h-4 w-4 rounded border-gray-300 text-green-600 focus:ring-green-500"
                        />
                        <Label htmlFor="confirmDemo" className="text-sm text-gray-600 cursor-pointer">
                            I confirm this is a demo payment
                        </Label>
                    </div>

                    <div className="bg-green-50 p-3 rounded-lg mt-4">
                        <div className="flex justify-between items-center">
                            <span className="text-sm text-gray-600">Total Amount:</span>
                            <span className="text-lg font-bold text-green-700">₹{booking?.rent || '0'}</span>
                        </div>
                    </div>

                    <DialogFooter className="mt-4">
                        <Button
                            type="button"
                            variant="outline"
                            onClick={handleClose}
                            disabled={loading}
                        >
                            Cancel
                        </Button>
                        <Button
                            type="submit"
                            className="bg-green-600 hover:bg-green-700"
                            disabled={loading}
                        >
                            {loading ? (
                                <>
                                    <Loader2 className="h-4 w-4 mr-2 animate-spin" />
                                    Processing...
                                </>
                            ) : (
                                <>
                                    <Check className="h-4 w-4 mr-2" />
                                    Pay ₹{booking?.rent || '0'}
                                </>
                            )}
                        </Button>
                    </DialogFooter>
                </form>
            </DialogContent>
        </Dialog>
    );
};

export default PaymentModal;